    51
    52          light_get_block_info(iter, LIGHT_INFO_TYPE, &type, NULL);
    53
    54          if (type != LIGHT_SECTION_HEADER_BLOCK)
    55                  return NULL;
    56
    57          light_pcapng_file_info *file_info = calloc(1, sizeof(light_pcapng_file_info));
    58
    59          struct _light_section_header* section_header;
    60
    61          light_get_block_info(iter, LIGHT_INFO_BODY, &section_header, NULL);
    62          file_info->major_version = section_header->major_version;
    63          file_info->minor_version = section_header->minor_version;
    64
    65          light_option opt = light_get_option(iter, LIGHT_OPTION_SHB_HARDWARE);
