    68                  file_info->hardware_desc_size = light_get_option_length(opt);
    69                  file_info->hardware_desc = calloc(file_info->hardware_desc_size+1, sizeof(char));
    70                  memcpy(file_info->hardware_desc, (char*)light_get_option_data(opt), file_info->hardware_desc_size);
    71                  file_info->hardware_desc[file_info->hardware_desc_size] = '\0';
    72          }
    73          else
    74          {
    75                  file_info->hardware_desc_size = 0;
    76                  file_info->hardware_desc = NULL;
    77          }
    78
    79          opt = light_get_option(iter, LIGHT_OPTION_SHB_OS);
