     4  light_pcapng_t *light_pcapng_open_write(const char* file_path, light_pcapng_file_info *file_info, int compression_level)
     5  {
     6          DCHECK_NULLP(file_info, return NULL);
     7          DCHECK_NULLP(file_path, return NULL);
     8
     9          light_pcapng_t *pcapng = calloc(1, sizeof(struct _light_pcapng_t));
    10
    11          pcapng->file = light_open_compression(file_path, LIGHT_OWRITE, compression_level);
    12          pcapng->file_info = file_info;
    13
    14          DCHECK_ASSERT_EXP(pcapng->file != NULL, "could not open output file", return NULL);
    15
    16          pcapng->pcapng = NULL;
    17
    18          struct _light_section_header section_header;
    19          section_header.byteorder_magic = BYTE_ORDER_MAGIC;
    20          section_header.major_version = file_info->major_version;
    21          section_header.minor_version = file_info->minor_version;
    22          section_header.section_length = 0xFFFFFFFFFFFFFFFFULL;
    23          light_pcapng blocks_to_write = light_alloc_block(LIGHT_SECTION_HEADER_BLOCK, (const uint32_t*)&section_header, sizeof(section_header)+3*sizeof(uint32_t));
    24
    25          if (file_info->file_comment_size > 0)
    26          {
    27                  light_option new_opt = light_create_option(LIGHT_OPTION_COMMENT, file_info->file_comment_size, file_info->file_comment);
    28                  light_add_option(blocks_to_write, blocks_to_write, new_opt, LIGHT_FALSE);
    29          }
    30
    31          if (file_info->hardware_desc_size > 0)
    32          {
    33                  light_option new_opt = light_create_option(LIGHT_OPTION_SHB_HARDWARE, file_info->hardware_desc_size, file_info->hardware_desc);
    34                  light_add_option(blocks_to_write, blocks_to_write, new_opt, LIGHT_FALSE);
    35          }
    36
    37          if (file_info->os_desc_size > 0)
    38          {
    39                  light_option new_opt = light_create_option(LIGHT_OPTION_SHB_OS, file_info->os_desc_size, file_info->os_desc);
    40                  light_add_option(blocks_to_write, blocks_to_write, new_opt, LIGHT_FALSE);
    41          }
    42
    43          if (file_info->user_app_desc_size > 0)
    44          {
    45                  light_option new_opt = light_create_option(LIGHT_OPTION_SHB_USERAPPL, file_info->user_app_desc_size, file_info->user_app_desc);
    46                  light_add_option(blocks_to_write, blocks_to_write, new_opt, LIGHT_FALSE);
    47          }
    48
    49          light_pcapng next_block = blocks_to_write;
    50          int i = 0;
    51          for (i = 0; i < file_info->interface_block_count; i++)
    52          {
    53                  struct _light_interface_description_block interface_block;
    54                  interface_block.link_type = file_info->link_types[i];
    55                  interface_block.reserved = 0;
    56                  interface_block.snapshot_length = 0;
    57
    58                  light_pcapng iface_block_pcapng = light_alloc_block(LIGHT_INTERFACE_BLOCK, (const uint32_t*)&interface_block, sizeof(struct _light_interface_description_block)+3*sizeof(uint32_t));
    59                  light_add_block(next_block, iface_block_pcapng);
    60                  next_block = iface_block_pcapng;
    61          }
    62
    63          light_pcapng_to_file_stream(blocks_to_write, pcapng->file);
    64
    65
    66          light_pcapng_release(blocks_to_write);
    67
    68          return pcapng;
    69  }
