    71  light_pcapng_t *light_pcapng_open_append(const char* file_path)
    72  {
    73          DCHECK_NULLP(file_path, return NULL);
    74
    75          light_pcapng_t *pcapng = light_pcapng_open_read(file_path, LIGHT_TRUE);
    76          DCHECK_NULLP(pcapng, return NULL);
    77          light_close(pcapng->file);
    78
    79          pcapng->file = light_open(file_path, LIGHT_OAPPEND);
    80          DCHECK_NULLP(pcapng->file, return NULL);
    81
    82          light_pcapng_release(pcapng->pcapng);
    83          pcapng->pcapng = NULL;
    84
    85          return pcapng;
    86  }
